 "content": "def transform(grid):
    """Fill the spaces between aligned marker cells, preserving all other cells."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    marker = 9 if any(9 in row for row in grid) else 7
    fill = 3

    # Fill horizontally between the outermost markers in each row.
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if out[r][c] != marker:
                    out[r][c] = fill

    # Fill vertically between the outermost markers in each column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if out[r][c] != marker:
                    out[r][c] = fill
    return out
